begin;
alter table public.attachments add column original_path text unique,add column original_sha256 text,add column original_mime text,add column original_bytes integer;
create unique index verified_student_number on public.profiles(student_number) where membership='approved' and student_number is not null and student_number<>'';
create or replace function public.on_signup() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id) values(new.id);insert into public.roles(user_id,role,approved) values(new.id,'student',false);return new;end; $$;
create or replace function public.can_read_submission(sid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.submissions s join public.events e on e.id=s.event_id join public.profiles p on p.id=auth.uid() where s.id=sid and p.membership='approved' and (s.student_id=auth.uid() or public.is_admin(e.department_id) or exists(select 1 from public.referrals r join public.offerings o on o.id=r.offering_id where r.submission_id=s.id and r.instructor_id=auth.uid() and o.approved and public.has_role('instructor',o.department_id)))); $$;
create or replace function public.can_read_attachment(aid uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.attachments a join public.submissions s on s.id=a.submission_id join public.events e on e.id=s.event_id join public.profiles p on p.id=auth.uid() where a.id=aid and p.membership='approved' and (s.student_id=auth.uid() or public.is_admin(e.department_id) or exists(select 1 from public.referrals r join public.offerings o on o.id=r.offering_id where r.submission_id=s.id and (r.attachment_id=a.id or exists(select 1 from public.assessments aa where aa.referral_id=r.id and aa.attachment_id=a.id)) and r.instructor_id=auth.uid() and o.approved and public.has_role('instructor',o.department_id)))); $$;
create function public.record_original(p_id uuid,p_hash text,p_mime text,p_bytes integer) returns text language plpgsql security definer set search_path='' as $$ declare path text;begin update public.attachments set original_path=object_path||'.original',original_sha256=p_hash,original_mime=p_mime,original_bytes=p_bytes where id=p_id and safety='pending' returning original_path into path;return path;end; $$;
drop policy summary_select on storage.objects;
create policy summary_select on storage.objects for select to authenticated using(bucket_id='summaries' and exists(select 1 from public.attachments a where (a.object_path=name or a.original_path=name) and public.can_read_attachment(a.id)));
grant select,delete on public.attachments to service_role;
revoke all on function public.record_original(uuid,text,text,integer) from public,anon,authenticated;
grant execute on function public.record_original(uuid,text,text,integer) to service_role;
create or replace function public.guard_assessment() returns trigger language plpgsql security definer set search_path='' as $$ begin
 if not exists(select 1 from public.referrals r join public.offerings o on o.id=r.offering_id join public.submissions s on s.id=r.submission_id join public.events e on e.id=s.event_id where r.id=new.referral_id and e.status='published' and e.club_approved and o.approved) then raise exception 'event or teaching association no longer eligible';end if;return new;end; $$;
commit;
